import React from "react";
import AdminNavbar from "../Components/AdminNavbar";

const AdminLayout = ({ children }) => {
  return (
    <>
      <AdminNavbar />
      <div style={{ padding: "20px" }}>
        {children}
      </div>
    </>
  );
};

export default AdminLayout;
